Contract LibraryManagementSystemSystem::borrowBook(uid:String,barcode:String): Boolean {

            precondition:
          User.allInstances()->one(u: User | u.UserID = uid) and BookCopy.allInstances()->one(c: BookCopy | c.Barcode = barcode) and let u: User = User.allInstances()->any(x: User | x.UserID = uid), c: BookCopy = BookCopy.allInstances()->any(y: BookCopy | y.Barcode = barcode) in u.BorrowStatus = BorrowStatus::NORMAL and u.SuspensionDays = 0 and (Student.allInstances()->exists(s: Student | s.UserID = uid and s.Programme = Programme::BACHELOR and s.LoanedNumber < 20) or Student.allInstances()->exists(s: Student | s.UserID = uid and s.Programme = Programme::MASTER and s.LoanedNumber < 40) or Student.allInstances()->exists(s: Student | s.UserID = uid and s.Programme <> Programme::BACHELOR and s.Programme <> Programme::MASTER and s.LoanedNumber < 60) or Faculty.allInstances()->exists(f: Faculty | f.UserID = uid and f.LoanedNumber < 60)) and (c.Status = CopyStatus::AVAILABLE or (c.Status = CopyStatus::ONHOLDSHELF and c.IsReserved = true and c.ReservationRecord->exists(r: Reserve | r.ReservedUser.UserID = uid and r.IsReserveClosed = false)))

            postcondition:
          let u: User = User.allInstances()->any(x: User | x.UserID = uid), c: BookCopy = BookCopy.allInstances()->any(y: BookCopy | y.Barcode = barcode) in Loan.allInstances()->one(l: Loan | l.oclIsNew() and l.LoanedUser = u and l.LoanedCopy = c and l.IsReturned = false and l.LoanDate = Today and l.ReturnDate = null and l.RenewedTimes = 0 and l.OverDueFee = 0.0 and l.OverDue3Days = false and l.OverDue10Days = false and l.OverDue17Days = false and l.OverDue31Days = false and u.LoanedBook->includes(l) and c.LoanedRecord->includes(l) and if Student.allInstances()->exists(s: Student | s.UserID = uid) then l.DueDate = Today.After(30) else l.DueDate = Today.After(60) endif) and u.LoanedNumber = u.LoanedNumber@pre + 1 and c.Status = CopyStatus::LOANED and if c.Status@pre = CopyStatus::ONHOLDSHELF then c.IsReserved = false and c.ReservationRecord->exists(r: Reserve | r.ReservedUser.UserID = uid and r.IsReserveClosed@pre = false and r.IsReserveClosed = true) else true endif and result = true

        }
